   475→    this.consume(TokenType.TRY, 'try 키워드 필요');
   476→    this.consume(TokenType.COLON, ': 필요');
   477→
   478→    const body = this.parseBlock();
   479→    const handlers: AST.ExceptionHandler[] = [];
   480→
   481→    while (this.match(TokenType.EXCEPT)) {
   482→      let exceptionType: AST.Expression | undefined;
   483→      let name: string | undefined;
   484→
   485→      if (!this.check(TokenType.COLON)) {
