private compileTryStatement(stmt: any): void {
  // SETUP_TRY: except 핸들러 정보를 stack에 push
  // 인자: handler_count, except_offsets[], finally_offset
  const setupIndex = this.builder.getCurrentOffset();
  this.builder.emit(Opcode.SETUP_TRY, [
    stmt.handlers.length,  // handler count
    0,                      // placeholder for handler offsets (will be patched)
    stmt.finallyBody ? 1 : 0 // has finally block
  ]);

  // Try 본체 컴파일
  for (const s of stmt.body) {
    this.compileStatement(s);
  }

  // 정상 완료 시 except 블록들을 건너뜀
  const skipJumpIndex = this.builder.getCurrentOffset();
  this.builder.emit(Opcode.JUMP, [0]); // placeholder

  // Except 핸들러들 컴파일
  const handlerOffsets: number[] = [];
  for (const handler of stmt.handlers) {
    handlerOffsets.push(this.builder.getCurrentOffset());

    // 예외 변수가 있으면 로컬 변수로 등록
    if (handler.name) {
      const handlerReg = this.allocRegister();
      this.registerSymbol(handler.name, false, handlerReg);
      // 예외 객체가 register 0에 있다고 가정
      this.builder.emit(Opcode.LOAD_CONST, [handlerReg, 0]); // FIXME: 예외 객체 로드
    }

    // Handler 본체 컴파일
    for (const s of handler.body) {
      this.compileStatement(s);
    }

    // Handler 종료 후 finally로 이동
    this.builder.emit(Opcode.JUMP, [0]); // placeholder
  }

  // else 블록 (예외가 없을 때만 실행)
  if (stmt.elseBody) {
    for (const s of stmt.elseBody) {
      this.compileStatement(s);
    }
  }

  // finally 블록 (항상 실행)
  const finallyOffset = this.builder.getCurrentOffset();
  if (stmt.finallyBody) {
    for (const s of stmt.finallyBody) {
      this.compileStatement(s);
    }
  }

  // POP_TRY: handler stack에서 제거
  this.builder.emit(Opcode.POP_TRY, []);

  // FIXME: 점프 주소 패칭 필요
}

