/**
 * PyFree Lexer (토크나이저)
 * Python + FreeLang 코드를 토큰 스트림으로 변환
 *
 * 기능:
 * - Python 인덴트 처리 (INDENT/DEDENT)
 * - 문자열 파싱 (f-string 포함)
 * - 숫자 파싱 (int, float, hex, binary)
 * - 주석 제거 (# Python, // FreeLang)
 * - 혼합 문법 지원
 */

import {
  Token,
  TokenType,
  ALL_KEYWORDS,
  createToken,
  PYTHON_KEYWORDS,
  FREELANG_KEYWORDS,
} from './tokens';

export class PyFreeLexer {
  private source: string;
  private pos: number = 0;
  private line: number = 1;
  private column: number = 1;
  private tokens: Token[] = [];
  private indentStack: number[] = [0];
  private currentIndent: number = 0;
  private atLineStart: boolean = true;

  constructor(source: string) {
    this.source = source;
  }

  /**
   * 메인: 소스 코드를 토큰 스트림으로 변환
   */
  tokenize(): Token[] {
    this.tokens = [];
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.indentStack = [0];
    this.atLineStart = true;

    while (this.pos < this.source.length) {
      // 줄의 시작에서 인덴트 처리
      if (this.atLineStart && !this.isAtLineEnd()) {
        this.handleIndentation();
      }

      if (this.pos >= this.source.length) break;

      const ch = this.current();

      // 공백 스킵 (인덴트 후)
      if (ch === ' ' || ch === '\t') {
        this.advance();
        continue;
      }

      // 개행
      if (ch === '\n' || ch === '\r') {
        this.addToken(TokenType.NEWLINE, ch);
        if (ch === '\r' && this.peek() === '\n') this.advance();
        this.advance();
        this.line++;
        this.column = 1;
        this.atLineStart = true;
        continue;
      }

      // 주석 (Python)
      if (ch === '#') {
        this.skipComment();
        continue;
      }

      // 주석 (FreeLang)
      if (ch === '/' && this.peek() === '/') {
        this.skipComment();
        continue;
      }

      // 문자열
      if (ch === '"' || ch === "'") {
        this.tokenizeString();
        this.atLineStart = false;
        continue;
      }

      // f-string
      if (ch === 'f' && (this.peek() === '"' || this.peek() === "'")) {
        this.tokenizeString(true);
        this.atLineStart = false;
        continue;
      }

      // 숫자

